.segment	"CODE"

.proc	_add_step: near

.segment	"CODE"

;
; if(step_button_lockout > 0){
;
	lda     _step_button_lockout
;
; return; //still in lockout period
;
	beq     L29BA
;
; }
;
	rts
;
; update_steps_per_minute(); // calculate SPM before resetting the timer
;
L29BA:	jsr     _update_steps_per_minute
;
; sprite_timer = 0; //used for animation
;
	lda     #$00
	sta     _sprite_timer
;
; velocity += 100;
;
	lda     #$64
	clc
	adc     _velocity
	sta     _velocity
	bcc     L2526
	inc     _velocity+1
;
; if(velocity > 720){
;
L2526:	lda     _velocity
	cmp     #$D1
	lda     _velocity+1
	sbc     #$02
	lda     #$00
	bcc     L29B4
;
; velocity = 720;
;
	ldx     #$02
	lda     #$D0
	sta     _velocity
	stx     _velocity+1
;
; time_since_button_press = 0;
;
	lda     #$00
L29B4:	sta     _time_since_button_press
;
; steps++;
;
	lda     _steps
	ldx     _steps+1
	clc
	adc     #$01
	bcc     L252E
	inx
L252E:	sta     _steps
	stx     _steps+1
;
; step_button_lockout = FRAMES_PER_STEP; //lock out for a few frames to avoid double counting
;
	lda     #$0A
	sta     _step_button_lockout
;
; if(ones_step == 9){
;
	lda     _ones_step
	cmp     #$09
	bne     L29B9
;
; ones_step = 0;
;
	lda     #$00
	sta     _ones_step
;
; if(tens_step == 9){
;
	lda     _tens_step
	cmp     #$09
	bne     L29B8
;
; tens_step = 0;
;
	lda     #$00
	sta     _tens_step
;
; if(hundreds_step == 9){
;
	lda     _hundreds_step
	cmp     #$09
	bne     L29B7
;
; hundreds_step = 0;
;
	lda     #$00
	sta     _hundreds_step
;
; if(thousands_step == 9){
;
	lda     _thousands_step
	cmp     #$09
	bne     L29B6
;
; thousands_step = 0;
;
	lda     #$00
	sta     _thousands_step
;
; if(ten_thousands_step == 9){
;
	lda     _ten_thousands_step
	cmp     #$09
	bne     L29B5
;
; ten_thousands_step = 0;
;
	lda     #$00
	sta     _ten_thousands_step
;
; } else {
;
	rts
;
; ten_thousands_step++;
;
L29B5:	inc     _ten_thousands_step
;
; } else {
;
	rts
;
; thousands_step++;
;
L29B6:	inc     _thousands_step
;
; } else {
;
	rts
;
; hundreds_step++;
;
L29B7:	inc     _hundreds_step
;
; } else {
;
	rts
;
; tens_step++;
;
L29B8:	inc     _tens_step
;
; } else {
;
	rts
;
; ones_step++;
;
L29B9:	inc     _ones_step
;
; }
;
	rts

.endproc

